import pandas as pd

def peak_calling_hours(calls: pd.DataFrame) -> pd.DataFrame:
    if calls.empty:
        return pd.DataFrame(columns=['city', 'peak_calling_hour', 'number_of_calls'])
    df = calls.copy()
    df['peak_calling_hour'] = pd.to_datetime(df['call_time']).dt.hour
    grouped = df.groupby(['city', 'peak_calling_hour']).size().reset_index(name='number_of_calls')
    grouped['rk'] = grouped.groupby('city')['number_of_calls'].rank(method='min', ascending=False)
    res = grouped[grouped['rk'] == 1][['city', 'peak_calling_hour', 'number_of_calls']]
    return res.sort_values(by=['peak_calling_hour', 'city'], ascending=[False, False])
